+                    throw new CommandException(e);
                 }

             }
         }

         List<CoordinatorActionBean> coordActions = new ArrayList<CoordinatorActionBean>();
         for (CoordinatorActionBean coordAction : actionSet) {
             coordActions.add(coordAction);
         }
         return coordActions;
